repo_files.log_reader.py:
"""Log sequential reader and filter."""

from typing import List
from wal_entry import WALEntry


class WALLogReader:
    def __init__(self, entries: List[WALEntry]):
        self.entries = list(entries)

    def get_entries_since(self, after_lsn: int) -> List[WALEntry]:
        # BUG: Uses >= instead of > when filtering after_lsn, re-applying the checkpoint entry itself!
        return [e for e in self.entries if e.lsn >= after_lsn]

repo_files.state_engine.py:
"""Database recovery and replay state engine."""

from typing import Any, Dict
from checkpoint import CheckpointState
from log_reader import WALLogReader


class RecoveryEngine:
    def __init__(self, reader: WALLogReader):
        self.reader = reader

    def recover(self, cp: CheckpointState) -> Dict[str, Any]:
        state = dict(cp.data)
        # Replay log entries committed strictly AFTER checkpoint_lsn
        entries = self.reader.get_entries_since(cp.checkpoint_lsn)
        for e in entries:
            if e.op_type == "SET":
                state[e.key] = e.value
            elif e.op_type == "DEL":
                state.pop(e.key, None)
        return state

